// Auto-generated terrain + coordinate map for map.svg
// Generated by full-resolution pixel scan of web/public/map.svg (1425x678).
// DO NOT EDIT MANUALLY — regenerate via the pixel-scan pipeline.
//
// Method: map.svg rasterized at native 1425x678 with landHeights opacity
// forced to 1 and noise layers (vignette/coordinates/scaleBar/coastline/ice)
// hidden, then every pixel nearest-color-matched against the SVG's own
// extracted palettes:
//   ocean   = #2d788b base + oceanHeights ramp blended 0.5  -> 'O'
//   land    = landHeights spectral ramp (green->yellow->orange->red)
//             bucketed: lowland 'l', midland 'm', highland 'h', mountain 'M'
//   water   = lakes #a6c1fd / rivers #2e89c2                 -> 'L'
//   coast   = land cell bordering ocean (derived)            -> 'c'
//
// Verified land mass (largest connected non-ocean component):
//   SVG x: 163 .. 1173   (width 1010px)
//   SVG y: 93 .. 621   (height 528px)
// Southern coastline (per-column southernmost land pixel):
//   min y=335  mean y=514.8  median y=536  max y=621
//   LAND_SVG_Y_MAX uses the southernmost extent (621) so the full
//   landmass fits the sim's vertical range; the irregular coast shape itself
//   is encoded in TERRAIN (see tileToTerrain).
//
// Legend: O=ocean  c=coast  l=lowland  m=midland  h=highland  M=mountain  L=lake/river

export const SVG_W = 1425;
export const SVG_H = 678;

// Sim grid dimensions (3000 x 1500). Rows 0..COAST_Y are land-mappable;
// rows >= VESSEL_Y_START represent vessels out at sea.
const SIM_W = 3000;
const SIM_H = 1500;
const COAST_Y = 1499;
const VESSEL_Y_START = 1500;

// Verified SVG land bounds (from full-resolution pixel scan).
const LAND_SVG_X_MIN = 163;
const LAND_SVG_X_MAX = 1173;
const LAND_SVG_Y_MIN = 93;
const LAND_SVG_Y_MAX = 621;
// Open-sea Y for vessels, south of the coastline (land ends at y=621, canvas at 678).
const VESSEL_SVG_Y = 650;

// Terrain grid: 600x300 chars, one per cell, row-major.
// Row 0 = north (SVG y=93), row 299 = south (SVG y=621).
// Each cell spans a proportional slice of the land bbox, sampled identically
// to tileToSvg so tileToTerrain and tileToSvg stay perfectly consistent.
export const TERRAIN_W = 600;
export const TERRAIN_H = 300;
export const TERRAIN: string = '';

// Legacy lookups — kept for compatibility.
export const TILE_COORDS: [number, number][] = [];
export const VESSEL_COORDS: Record<number, [number, number]> = {
  30: [700, 638],
  31: [700, 650],
};

export function tileToSvg(tileX: number, tileY: number): [number, number] {
  const svgX = LAND_SVG_X_MIN + (tileX / SIM_W) * (LAND_SVG_X_MAX - LAND_SVG_X_MIN);
  // Vessel zone (out at sea, south of the coast)
  if (tileY >= VESSEL_Y_START) {
    return [svgX, VESSEL_SVG_Y];
  }
  // Map sim coords proportionally onto the verified land bbox.
  const svgY = LAND_SVG_Y_MIN + (tileY / COAST_Y) * (LAND_SVG_Y_MAX - LAND_SVG_Y_MIN);
  return [svgX, svgY];
}

// Terrain type at a sim tile: 'O' ocean, 'c' coast, 'l' lowland,
// 'm' midland, 'h' highland, 'M' mountain, 'L' lake/river.
export function tileToTerrain(tileX: number, tileY: number): string {
  if (tileY >= VESSEL_Y_START) return 'O';
  const col = Math.min(TERRAIN_W - 1, Math.max(0, Math.floor((tileX / SIM_W) * TERRAIN_W)));
  const row = Math.min(TERRAIN_H - 1, Math.max(0, Math.floor((tileY / COAST_Y) * TERRAIN_H)));
  return TERRAIN[row * TERRAIN_W + col] ?? 'O';
}
